from collections import deque

def transform(grid):
    H,W=len(grid),len(grid[0])
    seen=set(); objs=[]
    for r in range(H):
        for c in range(W):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            r0=min(x for x,y in cells); c0=min(y for x,y in cells)
            cells=[(x-r0,y-c0) for x,y in cells]
            h=max(x for x,y in cells)+1; w=max(y for x,y in cells)+1
            objs.append((c0,r0,color,cells,h,w))
    objs.sort(key=lambda o:(o[0],o[1]))
    out=[[0]*W for _ in range(H)]
    ar=ac=0
    prev=None
    for c0,r0,color,cells,h,w in objs:
        if prev is not None:
            ar += prev[0]-1; ac += prev[1]-1
        for dr,dc in cells:
            if 0<=ar+dr<H and 0<=ac+dc<W: out[ar+dr][ac+dc]=color
        prev=(h,w)
    return out

def parse(s): return [[int(x) for x in line.split()] for line in s.strip().splitlines()]
